def merge_intervals(intervals):
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [[ivs[0][0], ivs[0][1]]]
    for s, e in ivs[1:]:
        if s <= merged[-1][1]:
