def max_non_overlapping(intervals):
    if not intervals:
        return 0
    ivs = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_end = None
    for a, b in ivs:
        if last_end is None or a > last_end:
            count += 1
            last_end = b
    return count
```

